const items=$input.all();
const result=[];
for(let i=0;i<items.length;i++){
 const mail=items[i];
 for(const [key,b] of Object.entries(mail.binary||{})){
  const name=String(b.fileName||'attachment.pdf');
  if(!name.toLowerCase().endsWith('.pdf') && b.mimeType!=='application/pdf') continue;
  const bytes=await this.helpers.getBinaryDataBuffer(i,key);
  if(bytes.length>20*1024*1024)throw new Error('PDF exceeds 20 MiB: '+name);
  if(!(mail.json.id||mail.json.messageId))throw new Error('Missing Gmail message ID');
  result.push({json:{messageId:mail.json.id||mail.json.messageId||'',subject:mail.json.subject||'',sender:typeof mail.json.from==='string'?mail.json.from:(mail.json.from?.text||''),attachmentKey:key,originalFileName:name},binary:{data:b},pairedItem:{item:i}});
 }
}
return result;

// EDIT THIS NODE: set the Google Drive folder ID and classification rules.
const config={
  driveFolderId:'REPLACE_WITH_DRIVE_FOLDER_ID',
  defaultCurrency:'EUR',
  maxPdfTextChars:100000,
  enableOCR:false, // Optional: connect an OCR endpoint before enabling
  enableAI:false, // Optional: connect an OpenAI-compatible endpoint before enabling
  ocrEndpoint:'https://example.invalid/ocr',
  aiModel:'REPLACE_WITH_MODEL',
  aiEndpoint:'https://example.invalid/v1/chat/completions',
  reportEmail:'', // Optional: one digest per completed execution
  labelProcessed:'', // Optional Gmail label ID
  labelReview:'', // Optional Gmail label ID
  categories:[
    {name:'Utilities',keywords:['electricity','gas bill','energy invoice','utility']},
    {name:'Internet',keywords:['broadband','internet service','telecom']},
    {name:'Cloud',keywords:['cloud computing','cloud services','hosting','server']}
  ]
};
if(!config.driveFolderId || config.driveFolderId.startsWith('REPLACE_'))throw new Error('Set driveFolderId in Configuration');
for(const [enabled,endpoint] of [[config.enableOCR,config.ocrEndpoint],[config.enableAI,config.aiEndpoint]]){if(enabled){const match=/^https:\/\/([^\/?#\s]+)(?:[\/?#]|$)/i.exec(String(endpoint));if(!match||/(?:^|\.)invalid(?::\d+)?$/i.test(match[1]))throw new Error('Configure a real HTTPS endpoint before enabling OCR/AI');}}
if(config.enableAI&&(!config.aiModel||config.aiModel.startsWith('REPLACE_')))throw new Error('Configure aiModel before enabling AI');
return {...$input.item,json:{...$input.item.json,config}};

function validISODate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const date = new Date(`${value}T00:00:00.000Z`);
  return Number.isFinite(date.getTime()) && date.toISOString().slice(0, 10) === value;
}
function parseDate(value) {
  const parts = value.split(/[./-]/).map(Number);
  if (parts.length !== 3) return '';
  const [a,b,c] = parts;
  const [year,month,day] = a > 1900 ? [a,b,c] : [c < 100 ? 2000+c : c,b,a];
  const date = `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
  return validISODate(date) ? date : '';
}
function money(value) {
  if (!/^-?\d[\d.,]*$/.test(value)) return null;
  let normalized;
  if (value.includes(',') && value.includes('.')) {
    const decimal = value.lastIndexOf(',') > value.lastIndexOf('.') ? ',' : '.';
    const grouping = decimal === ',' ? '.' : ',';
    const pattern = decimal === ',' ? /^-?\d{1,3}(?:\.\d{3})+,\d{2}$/ : /^-?\d{1,3}(?:,\d{3})+\.\d{2}$/;
    if (!pattern.test(value)) return null;
    normalized = value.split(grouping).join('').replace(decimal,'.');
  } else {
    if (!/^-?\d+(?:[.,]\d{1,2})?$/.test(value)) return null;
    normalized = value.replace(',','.');
  }
  const result = Number(normalized);
  return Number.isFinite(result) ? result : null;
}
function classify(text, subject, config) {
  const lower = `${text.slice(0,3500)} ${subject || ''}`.toLowerCase();
  return (config.categories.find(c => c.keywords.some(k => lower.includes(k.toLowerCase()))) || {}).name || 'Other';
}
function identity(vendor, invoiceNumber, invoiceDate) {
  const uniqueKey = [vendor,invoiceNumber,invoiceDate].map(s => encodeURIComponent(s.normalize('NFKC').trim().toLowerCase())).join(':');
  // Keep readable names while distinguishing punctuation and long identifiers.
  let hash = 0xcbf29ce484222325n;
  for (let i=0;i<uniqueKey.length;i++) hash = BigInt.asUintN(64,(hash ^ BigInt(uniqueKey.charCodeAt(i))) * 0x100000001b3n);
  const clean = (s,fallback) => s.normalize('NFKD').replace(/[^a-zA-Z0-9_-]+/g,'-').replace(/^-|-$/g,'').slice(0,55) || fallback;
  return {uniqueKey,fileName:`${invoiceDate}_${clean(vendor,'vendor')}_${clean(invoiceNumber,'invoice')}_${hash.toString(16).padStart(16,'0')}.pdf`};
}

const source = $input.item;
const cfg = source.json.config;
const raw = String(source.json.text || source.json.data || '').slice(0,cfg.maxPdfTextChars || 100000).replace(/\r/g,'');
const fail = reason => ({json:{...source.json,extractionText:raw,status:'rejected',reason,processedAt:new Date().toISOString()},binary:source.binary});
if (raw.trim().length < 40) return fail('PDF has no extractable text; configure OCR or review the document');
const lines = raw.split('\n').map(x=>x.trim()).filter(Boolean);
const find = patterns => {for (const p of patterns) {const m=raw.match(p);if(m)return m[1].trim();}return '';};
const invoiceNumber = find([/(?:invoice\s*(?:number|no\.?|#)|fattura\s*(?:n\.?|numero)|rechnungsnummer)\s*[:#-]?\s*([A-Z0-9][A-Z0-9\/_-]{2,79})(?![A-Z0-9\/_-])/i]);
const invoiceDate = parseDate(find([/(?:invoice\s*date|data\s*fattura|rechnungsdatum|date\s*of\s*issue)\s*[:\s]*([0-9]{1,4}[./-][0-9]{1,2}[./-][0-9]{2,4})(?!\d)/i]));
const dueDateText = find([/(?:due\s*date|payment\s*due|scadenza(?:\s*pagamento)?|zahlbar\s*bis)\s*[:\s]*([0-9]{1,4}[./-][0-9]{1,2}[./-][0-9]{2,4})(?!\d)/i]);
const dueDate = dueDateText ? parseDate(dueDateText) : '';
const total = find([/(?:grand\s*total|total\s*(?:due|amount|invoice)|amount\s*due|totale\s*(?:fattura|da\s*pagare|complessivo)|gesamtbetrag)\s*:?\s*(?:(?:EUR|USD|GBP|[€$£])\s*)?(-?\d[\d.,]*)(?![\d.,])/i]);
const amount = total ? money(total) : null;
const currency = /\bUSD\b|\$/.test(raw) ? 'USD' : /\bGBP\b|£/.test(raw) ? 'GBP' : /\bEUR\b|€/.test(raw) ? 'EUR' : cfg.defaultCurrency;
const vendorLine = lines.find(x=>/^(?:supplier|vendor|fornitore|seller)\s*:/i.test(x));
const vendor = (vendorLine ? vendorLine.replace(/^[^:]+:\s*/,'') : lines.find(x=>/[A-Za-z]{3,}/.test(x) && !/(invoice|fattura|date|data|bill to|total due)/i.test(x)) || '').trim();
if (!invoiceNumber || !invoiceDate || amount === null || !vendor || vendor.length > 80) return fail('Missing or invalid invoice number, date, total or vendor');
if (!/^[A-Z]{3}$/.test(currency)) return fail('Invalid currency');
if (amount < 0 || amount > 100000000) return fail('Negative or unusually large total requires manual review');
if (dueDateText && !dueDate) return fail('Invalid due date');
if (dueDate && dueDate < invoiceDate) return fail('Due date precedes invoice date');
return {json:{...source.json,status:'validated',reason:'',extractionText:raw,extractionMethod:source.json.extractionMethod || 'rules',invoiceNumber,invoiceDate,dueDate,amount,currency,vendor,category:classify(raw,source.json.subject,cfg),...identity(vendor,invoiceNumber,invoiceDate),processedAt:new Date().toISOString()},binary:source.binary};

const src=$('Restore validated PDF').item.json;
const id=$input.item.json.id||$input.item.json.fileId||'';
if(!id)throw new Error('Drive upload returned no file ID');
return {json:{uniqueKey:src.uniqueKey,invoiceNumber:src.invoiceNumber,vendor:src.vendor,invoiceDate:src.invoiceDate,dueDate:src.dueDate||"",amount:src.amount,currency:src.currency,category:src.category,fileName:src.fileName,driveFileId:id,status:'archived',sourceMessageId:src.messageId,processedAt:new Date().toISOString()}};

