const src = $('Parse & validate invoice').item;
const fail = reason => ({json:{...src.json,status:'rejected',reason},binary:src.binary});
let obj;
try {obj = JSON.parse($json.choices?.[0]?.message?.content || '{}');}
catch {return fail('AI response is not valid JSON');}
if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return fail('AI response is not an invoice object');
const vendor = typeof obj.vendor === 'string' ? obj.vendor.trim() : '';
const invoiceNumber = typeof obj.invoiceNumber === 'string' ? obj.invoiceNumber.trim() : '';
const invoiceDate = String(obj.invoiceDate || '');
const dueDate = String(obj.dueDate || '');
const currency = String(obj.currency || src.json.config.defaultCurrency).toUpperCase();
const amount = obj.amount;
if (!vendor || vendor.length > 80 || !invoiceNumber || invoiceNumber.length > 80 || !validISODate(invoiceDate) || typeof amount !== 'number' || !Number.isFinite(amount) || amount < 0 || amount > 100000000 || !/^[A-Z]{3}$/.test(currency)) return fail('AI could not validate required fields');
if (dueDate && (!validISODate(dueDate) || dueDate < invoiceDate)) return fail('AI returned an invalid due date');
